import pathlib, subprocess, re
p=pathlib.Path('dead-signal-mobile/index.html')
s=p.read_text(encoding='utf-8')
pairs=[["job,diff,name,H:100,E:80,Q:80,S:100,P:0,I:0,F:12,W:12","job,diff:3,name,H:100,E:80,Q:80,S:100,P:0,I:0,F:3,W:3"],["s.F+=2;s.W+=2","s.F+=1;s.W+=1"],["let before=s[k];if(RES.includes(k)){if(n>0){n=Math.max(1,Math.round(n*[1.4,1,.85,.7][s.diff]));}","let before=s[k];s.diff=3;if(RES.includes(k)){if(n>0){if(k==='F'||k==='W'){let visit=s.scarcityVisit??0;let factor=Math.max(0,1-visit*.35)*(s.E<=40?.8:1)*(s.Q<=40?.8:1);let roll=rnd(s);let early=Math.max(0,1-(s.day-1)/29);let p=(context.startsWith('편의점 탐색')?(k==='F'?.38+.27*early:.42+.28*early):context.startsWith('대형마트 탐색')?(k==='F'?.45+.30*early:.50+.30*early):(k==='F'?.25+.25*early:.30+.25*early))*factor*Math.max(.55,1-Math.max(0,s.day-30)*.45/70);n=roll>=p?0:roll<p*.04?3:roll<p*.20?2:1;}else n=Math.max(1,Math.round(n*.7));}"],["let ch=apply(s,code,LOCS[i]+' 탐색 '+(danger?'좀비':' '));","s.scarcityVisit=count;let ch=apply(s,code,LOCS[i]+' 탐색 '+(danger?'좀비':' '));delete s.scarcityVisit;"],["if(rnd(s)<.72){let id=pool[Math.floor(rnd(s)*pool.length)];give(s,id);ch.push(ITEMS[id]+' 발견')}","if(rnd(s)<Math.max(0,.24-count*.08)){let id=pool[Math.floor(rnd(s)*pool.length)];if(!(id>=14&&id<28||id===35)||rnd(s)<.20){give(s,id);ch.push(ITEMS[id]+' 발견')}}"],["danger?'감염자와 마주쳤다. 가까스로 물자를 챙겨 돌아왔다.':'폐허를 수색해 물자를 확보했다.'","danger?'감염자와 마주쳤다. 가까스로 돌아왔다.':ch.some(x=>/식량 \\+|물 \\+|발견/.test(x))?'폐허에서 남은 물자를 찾았다.':'이미 누군가 다녀간 자리였다. 식량과 물은 발견하지 못했다.'"],["if(flag(s,'purifier')){s.W++;ch.push('정수기 · 물 +1')}if(flag(s,'garden')&&s.day%3===0){s.F+=3;ch.push('텃밭 · 식량 +3')}","if(flag(s,'purifier')&&rnd(s)<.35){s.W++;ch.push('정수기 · 물 +1')}if(flag(s,'garden')&&s.day%3===0&&rnd(s)<.4){s.F++;ch.push('텃밭 · 식량 +1')}"],["diffPick=1","diffPick=3"],["state=x.state;if(x.archive)","state=x.state;state.diff=3;if(x.archive)"],["s.day<=100?s:null","s.day<=100?Object.assign(s,{diff:3}):null"],["V1.5 · SURVIVAL RATIONS / OFFLINE","V1.6 · SCARCITY / OFFLINE"],["<div class=\"formrow\"><label class=\"small\">난이도</label><select onchange=\"diffPick=+this.value\">${['스토리 · 자원 풍부','보통 · 권장','어려움 · 자원 부족','지옥 · 극한 생존'].map((d,i)=>`<option value=\"${i}\" ${i===diffPick?'selected':''}>${d}</option>`).join('')}</select></div>","<p class=\"notice\">초반에 물자를 비축하세요. 시간이 지날수록 도시 전체의 물자가 고갈됩니다. 굶주림과 탈수를 관리하세요.</p>"],["반복 방문 시 물자가 줄어듭니다.","시간이 지날수록 도시의 물자가 줄어들며 반복 방문 시 더욱 빠르게 고갈됩니다."],["tab=keepTab?previousTab:'survival';render(tab===previousTab?y:(tabScroll.survival||0))","pendingPopupTab=keepTab?previousTab:'survival';popupScroll=y;showStablePopup()"],["function closePopup(){if(!resultPopup)return;resultPopup=null;render(window.scrollY)}","let pendingPopupTab=null,popupScroll=0;function showStablePopup(){document.body.insertAdjacentHTML('beforeend',popupView(resultPopup));app.inert=true;document.body.classList.add('ds-popup-open');document.querySelector('.result-close')?.focus({preventScroll:true});}function closePopup(){if(!resultPopup)return;document.querySelector('body > .result-overlay')?.remove();app.inert=false;document.body.classList.remove('ds-popup-open');resultPopup=null;let previous=tab;tab=pendingPopupTab||tab;pendingPopupTab=null;render(tab===previous?popupScroll:(tabScroll[tab]||0))}"],["if(resultPopup&&screen==='game')view+=popupView(resultPopup);",""],["backdrop-filter:blur(4px);",""]]
for old,new in pairs:
 assert s.count(old)==1, (old[:80],s.count(old))
 s=s.replace(old,new,1)
css='html{scrollbar-gutter:stable}.result-overlay{background:rgba(7,9,11,.72);backdrop-filter:none!important;-webkit-backdrop-filter:none!important;overscroll-behavior:contain}.ds-popup-open #app{pointer-events:none}.ds-popup-open #app *, .ds-popup-open #app *:before,.ds-popup-open #app *:after{animation-play-state:paused!important}.ds-popup-open{overflow:hidden}.result-modal{overscroll-behavior:contain;animation:ds-popup-in .18s ease-out}@keyframes ds-popup-in{from{opacity:0}to{opacity:1}}@media(prefers-reduced-motion:reduce){.result-modal{animation:none}}'
s=s.replace('</style>',css+'</style>',1)
p.write_text(s,encoding='utf-8')
for i,script in enumerate(re.findall(r'<script>(.*?)</script>',s,re.S)):
 f=pathlib.Path('/tmp/dead-signal-check.js');f.write_text(script,encoding='utf-8');subprocess.run(['node','--check',str(f)],check=True)

# Rewarded revival test bridge; production adapter returns true only on earned reward.
revival = "\nlet reviveBusy=false;\nfunction canRevive(s){return !!s&&s.ending>=23&&s.ending<=30&&!s.reviveUsed}\nasync function reviveAd(){\n const s=state;if(reviveBusy||!canRevive(s)||screen!=='end')return;\n reviveBusy=true;render();\n try{\n let earned=false;\n if(typeof window.deadSignalRewardedAd==='function'){earned=await window.deadSignalRewardedAd()===true}\n else {earned=confirm('테스트 광고입니다. 광고 시청 완료를 확인하시겠습니까?');}\n if(!earned||state!==s||!canRevive(s)||screen!=='end')return;\n s.reviveUsed=true;s.ending=0;s.H=50;s.E=Math.max(s.E,40);s.Q=Math.max(s.Q,40);s.S=Math.max(s.S,40);s.P=Math.min(s.P,60);s.I=Math.min(s.I,50);\n s.phase='night';s.secret=-1;s.action=null;s.freeUsed=true;\n note(s,'부활권 사용','간신히 살아 돌아왔다. 이번 회차의 부활권을 모두 사용했다.',['체력 50','포만감·수분 최소 40']);\n if(s.day>=100){finish(s)}\n save();resultPopup=null;clearTabScroll();tab='survival';show(s.ending?'end':'game');\n }catch(e){toast('광고를 완료하지 못했습니다. 다시 시도해주세요.')}finally{reviveBusy=false;if(screen==='end')render()}\n}\nconst dsEndOriginal=endView;\nendView=function(){let html=dsEndOriginal();if(!canRevive(state))return html;return html.replace('<div class=\"endbuttons\">',`<div class=\"notice\" style=\"border-color:#bca06b;margin-top:16px\"><div class=\"label\">SECOND CHANCE · 1회 한정</div><h2>아직 끝나지 않았다.</h2><p>광고 1회 시청 후 부활할 수 있습니다. 보유 물자는 그대로 유지됩니다.</p><button class=\"primary\" style=\"width:100%\" onclick=\"reviveAd()\" ${reviveBusy?'disabled':''}>${reviveBusy?'광고 확인 중…':'▶ 광고 보고 부활하기 (1/1)'}</button><p class=\"small\">현재는 테스트 광고입니다. 회차당 1회만 사용 가능합니다.</p></div><div class=\"endbuttons\">`)};\n"
assert s.count('render();\n</script></body></html>') == 1
s=s.replace('render();\n</script></body></html>',revival+'\nrender();\n</script></body></html>',1)
s=s.replace('V1.6 · SCARCITY / OFFLINE','V1.7 · SECOND CHANCE / OFFLINE')
p.write_text(s,encoding='utf-8')
for script in re.findall(r'<script>(.*?)</script>',s,re.S):
 f=pathlib.Path('/tmp/dead-signal-check.js');f.write_text(script,encoding='utf-8');subprocess.run(['node','--check',str(f)],check=True)

# Optional rewarded supply drops, separate from revival.
supply_ads = "\nlet supplyAdBusy=false;\nfunction supplyCount(k){return state?.supplyAds?.day===state.day?(state.supplyAds[k]||0):0}\nfunction openSupplyAds(){\n if(screen!=='game'||!state||state.ending||resultPopup||supplyAdBusy||document.getElementById('supply-ad-overlay'))return;\n const el=document.createElement('div');el.id='supply-ad-overlay';el.className='result-overlay';el.innerHTML=`<div class=\"result-modal\" role=\"dialog\" aria-modal=\"true\" aria-label=\"광고 보상\"><button class=\"result-close\" onclick=\"closeSupplyAds()\" aria-label=\"닫기\">×</button><div class=\"label\">SUPPLY DROP / 광고 보상</div><h2>긴급 보급품</h2><p class=\"bodycopy\">광고 1회 시청으로 원하는 물자를 받을 수 있습니다. 종류별 하루 1회.</p><div class=\"choices\">${[['F','식량'],['W','물']].map(([k,n])=>`<button class=\"choice\" onclick=\"claimSupplyAd('${k}')\" ${supplyCount(k)?'disabled':''}>${img('res'+k,'resource-icon')}<span>${n} +5<br><small>${supplyCount(k)?'오늘 수령 완료':'광고 시청 · 1/1'}</small></span><span class=\"arrow\">▶</span></button>`).join('')}</div><p class=\"small\">현재 테스트 광고 · 실제 광고는 추후 연결 예정</p><button class=\"plain\" style=\"width:100%\" onclick=\"closeSupplyAds()\">닫기</button></div>`;\n document.body.append(el);app.inert=true;document.body.classList.add('ds-popup-open');el.querySelector('.result-close')?.focus({preventScroll:true});\n}\nfunction closeSupplyAds(){if(supplyAdBusy)return;let el=document.getElementById('supply-ad-overlay');if(!el)return;el.remove();app.inert=false;document.body.classList.remove('ds-popup-open')}\nasync function claimSupplyAd(k){\n if(!['F','W'].includes(k)||!state||state.ending||screen!=='game'||supplyAdBusy||supplyCount(k)||!document.getElementById('supply-ad-overlay'))return;\n const s=state,day=s.day;supplyAdBusy=true;document.querySelectorAll('#supply-ad-overlay button').forEach(b=>b.disabled=true);\n try{\n let earned=typeof window.deadSignalRewardedAd==='function'?await window.deadSignalRewardedAd('supply_'+k)===true:confirm('테스트 광고입니다. 광고 시청을 완료하시겠습니까?');\n if(earned&&state===s&&s.day===day&&!s.ending&&screen==='game'&&!supplyCount(k)){\n if(s.supplyAds?.day!==day)s.supplyAds={day,F:0,W:0};\n s.supplyAds[k]=1;s[k]+=5;note(s,'광고 보급품','광고 보상으로 긴급 물자를 확보했다.',[(k==='F'?'식량':'물')+' +5']);save();\n }\n }catch(e){toast('광고를 완료하지 못했습니다.')}finally{supplyAdBusy=false;closeSupplyAds();if(screen==='game'&&state===s){render(window.scrollY);openSupplyAds()}}\n}\nconst supplyGameView=gameView;\ngameView=function(){return supplyGameView().replace('<button class=\"plain\" onclick=\"save();show(\\'title\\')\">메뉴</button>',`<div style=\"display:flex;gap:6px;align-items:center\"><button class=\"plain\" style=\"color:#d9b16c\" onclick=\"openSupplyAds()\">▶ 광고</button><button class=\"plain\" onclick=\"save();show('title')\">메뉴</button></div>`)};\ndocument.addEventListener('keydown',e=>{if(e.key==='Escape')closeSupplyAds()});\n"
assert s.count('render();\n</script></body></html>') == 1
s=s.replace('render();\n</script></body></html>',supply_ads+'\nrender();\n</script></body></html>',1)
s=s.replace('V1.7 · SECOND CHANCE / OFFLINE','V1.8 · SUPPLY DROP / OFFLINE')
p.write_text(s,encoding='utf-8')
for script in re.findall(r'<script>(.*?)</script>',s,re.S):
 f=pathlib.Path('/tmp/dead-signal-check.js');f.write_text(script,encoding='utf-8');subprocess.run(['node','--check',str(f)],check=True)
